/**
 * Trusted update-signing PUBLIC keys (Ed25519 + ML-DSA-65). See docs/RELEASE-RUNBOOK.md.
 *
 * !!! TEST / PLACEHOLDER KEYS — MUST BE REPLACED BEFORE THE FIRST REAL RELEASE !!!
 * Both slots below were generated by `tools/release/run.mjs gen-keys` for development; their private seeds were
 * destroyed immediately, so nothing can be signed for them and the updater will reject every release until real keys
 * from the offline key ceremony are pasted here (and `placeholder: true` removed). Release CI refuses to build while
 * any slot is marked placeholder.
 *
 * `current` signs releases today. `next` is the pre-distributed successor: shipping it in release N lets release N+1
 * be signed with it (rotation). Never put private key material in this repository.
 */
import type { TrustedUpdateKeys } from './verify';

export const UPDATE_KEYS: TrustedUpdateKeys = {
  current: {
    placeholder: true,
    id: '41f23c85077fa423',
    ed25519: 'l3w5sguTQufoovLVmxdnOawExjQSFAi0h1vdpg+UuUc=',
    mldsa65:
      '',
  },
  next: {
    placeholder: true,
    id: 'f79054bff1baa842',
    ed25519: 'g0kYkWC+oPQIjlSu+D3mqCqa9ys/iBdx65MZpMzdQR0=',
    mldsa65:
      '',
  },
};

/** True when any trusted slot is still a placeholder. */
export const UPDATE_KEYS_ARE_PLACEHOLDER: boolean =
  UPDATE_KEYS.current.placeholder === true || UPDATE_KEYS.next?.placeholder === true;
